7	using namespace AscendC;
8	
9	constexpr int64_t INDEX_BATCH_SIZE = 256;
10	
11	template<typename T, bool IS_FLOAT>
12	class InplaceIndexAddWithSortedKernel {
13	public:
14	    __aicore__ inline InplaceIndexAddWithSortedKernel() {}
15	    __aicore__ inline void Init(GM_ADDR output, GM_ADDR value, GM_ADDR sortedIndices, GM_ADDR pos,
16	                                 int64_t innerDim, int64_t indicesNum,
17	                                 int64_t formerNum, int64_t formerLength,
18	                                 int64_t tailNum, int64_t tailLength,
19	                                 int64_t tileLength, float alphaValue,
20	                                 int64_t alphaIsSet, int64_t usedCoreNum);
21	    __aicore__ inline void Process();
22	
23	private:
24	    __aicore__ inline void LoadValue(int64_t p, int64_t colOffset, int64_t length,
25	                                      LocalTensor<T> &valLocal);
26	    __aicore__ inline void WriteDelta(int64_t idx, int64_t colOffset, int64_t length,
27	                                       LocalTensor<T> &deltaLocal);
28	
29	    TPipe pipe;
30	    TBuf<TPosition::VECIN> valBuf;
31	    TBuf<TPosition::VECOUT> outBuf;
32	    TBuf<TPosition::VECIN> idxBuf;
33	    TBuf<TPosition::VECIN> posBuf;
34	    TBuf<TPosition::VECCALC> tmpBuf;
35	
36	    GlobalTensor<T> outputGm;
37	    GlobalTensor<T> valueGm;
38	    GlobalTensor<int32_t> sortedIndicesGm;
39	    GlobalTensor<int32_t> posGm;
40	
41	    int64_t innerDim_ = 0;
42	    int64_t indicesNum_ = 0;
43	    int64_t formerNum_ = 0;
44	    int64_t formerLength_ = 0;
45	    int64_t tailNum_ = 0;
46	    int64_t tailLength_ = 0;
47	    int64_t tileLength_ = 0;
48	    float alphaValue_ = 1.0f;
49	    int64_t alphaIsSet_ = 0;
50	    int64_t usedCoreNum_ = 0;
51	    int64_t idxStart_ = 0;
52	    int64_t idxEnd_ = 0;
53	};
54	
55	template<typename T, bool IS_FLOAT>
56	__aicore__ inline void InplaceIndexAddWithSortedKernel<T, IS_FLOAT>::Init(
57	    GM_ADDR output, GM_ADDR value, GM_ADDR sortedIndices, GM_ADDR pos,
58	    int64_t innerDim, int64_t indicesNum,
59	    int64_t formerNum, int64_t formerLength,
60	    int64_t tailNum, int64_t tailLength,
61	    int64_t tileLength, float alphaValue,
62	    int64_t alphaIsSet, int64_t usedCoreNum)
63	{
64	    innerDim_ = innerDim;
65	    indicesNum_ = indicesNum;
66	    formerNum_ = formerNum;
67	    formerLength_ = formerLength;
68	    tailNum_ = tailNum;
69	    tailLength_ = tailLength;
70	    tileLength_ = tileLength;
71	    alphaValue_ = alphaValue;
72	    alphaIsSet_ = alphaIsSet;
73	    usedCoreNum_ = usedCoreNum;
74	
75	    outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(output));
76	    valueGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(value));
77	    sortedIndicesGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(sortedIndices));
78	    posGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(pos));
79	
80	    int64_t blockIdx = GetBlockIdx();
81	    if (blockIdx < formerNum_) {
82	        idxStart_ = blockIdx * formerLength_;
83	        idxEnd_ = idxStart_ + formerLength_;
84	    } else {
85	        idxStart_ = formerNum_ * formerLength_;
86	        idxEnd_ = idxStart_ + tailLength_;
87	    }
88	
89	    pipe.InitBuffer(valBuf, tileLength_ * sizeof(T));
90	    pipe.InitBuffer(outBuf, tileLength_ * sizeof(T));
91	    int64_t idxBufSize = ((INDEX_BATCH_SIZE * sizeof(int32_t) + 31) / 32) * 32;
92	    pipe.InitBuffer(idxBuf, idxBufSize);
93	    pipe.InitBuffer(posBuf, idxBufSize);
94	
95	    if constexpr (IS_FLOAT && sizeof(T) == 2) {
96	        pipe.InitBuffer(tmpBuf, tileLength_ * sizeof(float));
97	    } else if constexpr (!IS_FLOAT && sizeof(T) == 2) {
98	        pipe.InitBuffer(tmpBuf, tileLength_ * sizeof(int32_t));
99	    } else if constexpr (!IS_FLOAT && sizeof(T) == 4) {
100	        pipe.InitBuffer(tmpBuf, tileLength_ * sizeof(float));
101	    }
102	}
103	
104	template<typename T, bool IS_FLOAT>
105	__aicore__ inline void InplaceIndexAddWithSortedKernel<T, IS_FLOAT>::LoadValue(
106	    int64_t p, int64_t colOffset, int64_t length, LocalTensor<T> &valLocal)
107	{
108	    DataCopyExtParams cp;
109	    cp.blockCount = 1;
110	    cp.blockLen = static_cast<uint32_t>(length * sizeof(T));
111	    cp.srcStride = 0;
112	    cp.dstStride = 0;
113	    DataCopyPadExtParams<T> pp;
114	    pp.isPad = false;
115	    DataCopyPad(valLocal, valueGm[p * innerDim_ + colOffset], cp, pp);
116	    PipeBarrier<PIPE_ALL>();
117	}
118	
119	template<typename T, bool IS_FLOAT>
120	__aicore__ inline void InplaceIndexAddWithSortedKernel<T, IS_FLOAT>::WriteDelta(
121	    int64_t idx, int64_t colOffset, int64_t length, LocalTensor<T> &deltaLocal)
122	{
123	    DataCopyExtParams cp;
124	    cp.blockCount = 1;
125	    cp.blockLen = static_cast<uint32_t>(length * sizeof(T));
126	    cp.srcStride = 0;
127	    cp.dstStride = 0;
128	
129	    SetAtomicAdd<T>();
130	    DataCopyPad(outputGm[idx * innerDim_ + colOffset], deltaLocal, cp);
131	    SetAtomicNone();
132	    PipeBarrier<PIPE_ALL>();
133	}
134	
135	template<typename T, bool IS_FLOAT>
136	__aicore__ inline void InplaceIndexAddWithSortedKernel<T, IS_FLOAT>::Process()
137	{
138	    int64_t blockIdx = GetBlockIdx();
139	    if (blockIdx >= usedCoreNum_) return;
140	
141	    int64_t total = idxEnd_ - idxStart_;
142	    if (total <= 0) return;
143	
144	    DataCopyPadExtParams<int32_t> idxPP;
145	    idxPP.isPad = false;
146	
147	    for (int64_t bs = 0; bs < total; bs += INDEX_BATCH_SIZE) {
148	        int64_t bsz = (bs + INDEX_BATCH_SIZE <= total) ? INDEX_BATCH_SIZE : (total - bs);
149	
150	        DataCopyExtParams cp;
151	        cp.blockCount = 1;
152	        cp.blockLen = static_cast<uint32_t>(bsz * sizeof(int32_t));
153	        cp.srcStride = 0;
154	        cp.dstStride = 0;
155	
156	        LocalTensor<int32_t> idxLocal = idxBuf.Get<int32_t>();
157	        DataCopyPad(idxLocal, sortedIndicesGm[idxStart_ + bs], cp, idxPP);
158	        LocalTensor<int32_t> posLocal = posBuf.Get<int32_t>();
159	        DataCopyPad(posLocal, posGm[idxStart_ + bs], cp, idxPP);
160	        PipeBarrier<PIPE_ALL>();
161	
162	        for (int64_t b = 0; b < bsz; b++) {
163	            int64_t myIdx = static_cast<int64_t>(idxLocal.GetValue(b));
164	            int64_t myPos = static_cast<int64_t>(posLocal.GetValue(b));
165	
166	            int64_t tileNum = (innerDim_ + tileLength_ - 1) / tileLength_;
167	            for (int64_t t = 0; t < tileNum; t++) {
168	                int64_t off = t * tileLength_;
169	                int64_t len = (t == tileNum - 1) ? (innerDim_ - off) : tileLength_;
170	
171	                // 1. Load value row
172	                LocalTensor<T> valLocal = valBuf.Get<T>();
173	                LoadValue(myPos, off, len, valLocal);
174	
175	                LocalTensor<T> outLocal = outBuf.Get<T>();
176	
177	                // 2. Compute delta = alpha * val
178	                if constexpr (IS_FLOAT && sizeof(T) == 4) {
179	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
180	                        Muls(outLocal, valLocal, alphaValue_, len);
181	                    } else {
182	                        Muls(outLocal, valLocal, 1.0f, len);
183	                    }
184	                } else if constexpr (IS_FLOAT && sizeof(T) == 2) {
185	                    LocalTensor<float> fp32 = tmpBuf.Get<float>();
186	                    Cast(fp32, valLocal, RoundMode::CAST_NONE, len);
187	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
188	                        Muls(fp32, fp32, alphaValue_, len);
189	                    }
190	                    Cast(outLocal, fp32, RoundMode::CAST_ROUND, len);
191	                } else if constexpr (!IS_FLOAT && sizeof(T) == 4) {
192	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
193	                        LocalTensor<float> fp32 = tmpBuf.Get<float>();
194	                        Cast(fp32, valLocal, RoundMode::CAST_NONE, len);
195	                        Muls(fp32, fp32, alphaValue_, len);
196	                        Cast(outLocal, fp32, RoundMode::CAST_ROUND, len);
197	                    } else {
198	                        Muls(outLocal, valLocal, static_cast<T>(1), len);
199	                    }
200	                } else {
201	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
202	                        int16_t as = static_cast<int16_t>(static_cast<int32_t>(alphaValue_));
203	                        Muls(outLocal, valLocal, as, len);
204	                    } else {
205	                        Muls(outLocal, valLocal, static_cast<int16_t>(1), len);
206	                    }
207	                }
208	
209	                // 3. AtomicAdd delta to output
210	                WriteDelta(myIdx, off, len, outLocal);
211	            }
212	        }
213	    }
214	}
