216	#define DEFINE_KERNEL_ENTRY(name_suffix, T, IS_FLOAT)                                         \
217	extern "C" __global__ __aicore__ void inplace_index_add_with_sorted_##name_suffix(           \
218	    GM_ADDR output, GM_ADDR value, GM_ADDR sorted_indices, GM_ADDR pos,                      \
219	    int64_t innerDim, int64_t indicesNum,                                                     \
220	    int64_t formerNum, int64_t formerLength,                                                  \
221	    int64_t tailNum, int64_t tailLength,                                                      \
222	    int64_t tileLength, float alphaValue,                                                     \
223	    int64_t alphaIsSet, int64_t usedCoreNum)                                                  \
224	{                                                                                             \
225	    InplaceIndexAddWithSortedKernel<T, IS_FLOAT> op;                                          \
226	    op.Init(output, value, sorted_indices, pos,                                               \
227	            innerDim, indicesNum, formerNum, formerLength,                                    \
228	            tailNum, tailLength, tileLength, alphaValue,                                      \
229	            alphaIsSet, usedCoreNum);                                                         \
230	    op.Process();                                                                             \
231	}
