21	
22	at::Tensor inplace_index_add_with_sorted(
23	    const at::Tensor &var,
24	    const at::Tensor &value,
25	    const at::Tensor &sorted_indices,
26	    const at::Tensor &pos,
27	    int64_t axis,
28	    const c10::optional<at::Tensor> &alpha)
29	{
30	    // ---- Input validation ----
31	    TORCH_CHECK(var.device().type() == at::DeviceType::PrivateUse1,
32	                "inplace_index_add_with_sorted: var must be on NPU device");
33	    TORCH_CHECK(value.device().type() == at::DeviceType::PrivateUse1,
34	                "inplace_index_add_with_sorted: value must be on NPU device");
35	    TORCH_CHECK(sorted_indices.device().type() == at::DeviceType::PrivateUse1,
36	                "inplace_index_add_with_sorted: sorted_indices must be on NPU device");
37	    TORCH_CHECK(pos.device().type() == at::DeviceType::PrivateUse1,
38	                "inplace_index_add_with_sorted: pos must be on NPU device");
39	
40	    TORCH_CHECK(axis == 0, "inplace_index_add_with_sorted: only axis=0 is supported");
41	
42	    auto dtype = var.scalar_type();
43	    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16 ||
44	                dtype == at::kInt || dtype == at::kShort,
45	                "inplace_index_add_with_sorted: unsupported dtype");
46	    TORCH_CHECK(dtype == value.scalar_type(),
47	                "inplace_index_add_with_sorted: var and value must have same dtype");
48	
49	    TORCH_CHECK(sorted_indices.dim() == 1, "inplace_index_add_with_sorted: sorted_indices must be 1D");
50	    TORCH_CHECK(pos.dim() == 1, "inplace_index_add_with_sorted: pos must be 1D");
51	    TORCH_CHECK(sorted_indices.size(0) == pos.size(0),
52	                "inplace_index_add_with_sorted: sorted_indices and pos must have same length");
53	
54	    // ---- Contiguous ----
55	    auto varContiguous = var.contiguous();
56	    auto valueContiguous = value.contiguous();
57	    auto sortedIndicesContiguous = sorted_indices.contiguous().to(at::kInt);
58	    auto posContiguous = pos.contiguous().to(at::kInt);
59	
60	    // ---- Create output (clone of var) ----
61	    auto output = varContiguous.clone();
62	
63	    // ---- Dimension parameters ----
64	    // For axis=0: var=[M, N], value=[V, N], indices=[K]
65	    int64_t innerDim = 1;
66	    for (int64_t d = 1; d < varContiguous.dim(); d++) {
67	        innerDim *= varContiguous.size(d);
68	    }
69	    int64_t indicesNum = sortedIndicesContiguous.size(0);
70	    int64_t dtypeSize = varContiguous.element_size();
71	
72	    // ---- Alpha extraction ----
73	    float alphaValue = 1.0f;
74	    int64_t alphaIsSet = 0;
75	    if (alpha.has_value() && alpha->defined()) {
76	        auto alphaCpu = alpha->to(at::kCPU);
77	        alphaValue = alphaCpu.item<float>();
78	        alphaIsSet = 1;
79	    }
80	
81	    // ---- Platform info ----
82	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
83	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
84	    uint64_t ubSize;
85	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
86	    int64_t ubSizeBytes = static_cast<int64_t>(ubSize);
87	
88	    // ---- Block-level tiling (divide indices across cores) ----
89	    // Use single core for correctness. AtomicAdd for fp16/bf16/int16 has known
90	    // limitations on current platform with multi-core; single-core avoids conflicts
91	    // while still being correct. Multi-core optimization can be added in a future
92	    // pass once platform AtomicAdd support for all dtypes is verified.
93	    int64_t usedCoreNum = 1;
94	    if (usedCoreNum < 1) usedCoreNum = 1;
95	    int64_t indicesPerCore = (indicesNum + usedCoreNum - 1) / usedCoreNum;
96	    int64_t formerNum = (usedCoreNum > 1) ? (usedCoreNum - 1) : 0;
97	    int64_t tailNum = (usedCoreNum > 0) ? 1 : 0;
98	    int64_t formerLength = indicesPerCore;
99	    int64_t tailLength = indicesNum - formerNum * formerLength;
100	
101	    // ---- UB-level tiling ----
102	    // bufferCoefficient per dtype (bytes per tile element):
103	    //   float32/int32: 32  (3q*2buf + 2tmp = 8 * 4B)
104	    //   float16/bf16:  24  (3q*2buf*2B + 3tmp*4B = 12+12)
105	    //   int16:         24  (same as fp16 pattern)
106	    int64_t bufferCoefficient;
107	    bool isFloatingPoint = true;
108	    if (dtype == at::kFloat) {
109	        bufferCoefficient = 32;
110	    } else if (dtype == at::kHalf || dtype == at::kBFloat16) {
111	        bufferCoefficient = 24;
112	    } else if (dtype == at::kInt) {
113	        bufferCoefficient = 32;
114	        isFloatingPoint = false;
115	    } else {  // kShort / int16
116	        bufferCoefficient = 24;
117	        isFloatingPoint = false;
118	    }
119	
120	    int64_t maxTileElements = ubSizeBytes / bufferCoefficient;
121	    int64_t alignElements = 32 / dtypeSize;
122	    if (alignElements < 1) alignElements = 1;
123	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
124	    if (tileLength < alignElements) tileLength = alignElements;
125	
126	    // Clamp tileLength to innerDim
127	    if (tileLength > innerDim) tileLength = innerDim;
128	
129	    // ---- Launch kernel ----
130	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
131	
132	    // All params must be LVALUES for EXEC_KERNEL_CMD
133	    int64_t innerDimParam = innerDim;
134	    int64_t indicesNumParam = indicesNum;
135	    int64_t formerNumParam = formerNum;
136	    int64_t formerLengthParam = formerLength;
137	    int64_t tailNumParam = tailNum;
138	    int64_t tailLengthParam = tailLength;
139	    int64_t tileLengthParam = tileLength;
140	    float alphaValueParam = alphaValue;
141	    int64_t alphaIsSetParam = alphaIsSet;
142	    int64_t usedCoreNumParam = usedCoreNum;
143	
144	    if (dtype == at::kFloat) {
145	        EXEC_KERNEL_CMD(inplace_index_add_with_sorted_fp32, blockDim,
146	            output, valueContiguous, sortedIndicesContiguous, posContiguous,
147	            innerDimParam, indicesNumParam, formerNumParam, formerLengthParam,
148	            tailNumParam, tailLengthParam, tileLengthParam, alphaValueParam,
149	            alphaIsSetParam, usedCoreNumParam);
150	    } else if (dtype == at::kHalf) {
151	        EXEC_KERNEL_CMD(inplace_index_add_with_sorted_half, blockDim,
152	            output, valueContiguous, sortedIndicesContiguous, posContiguous,
153	            innerDimParam, indicesNumParam, formerNumParam, formerLengthParam,
154	            tailNumParam, tailLengthParam, tileLengthParam, alphaValueParam,
155	            alphaIsSetParam, usedCoreNumParam);
156	    } else if (dtype == at::kBFloat16) {
157	        EXEC_KERNEL_CMD(inplace_index_add_with_sorted_bf16, blockDim,
158	            output, valueContiguous, sortedIndicesContiguous, posContiguous,
159	            innerDimParam, indicesNumParam, formerNumParam, formerLengthParam,
160	            tailNumParam, tailLengthParam, tileLengthParam, alphaValueParam,
161	            alphaIsSetParam, usedCoreNumParam);
162	    } else if (dtype == at::kInt) {
163	        EXEC_KERNEL_CMD(inplace_index_add_with_sorted_int32, blockDim,
164	            output, valueContiguous, sortedIndicesContiguous, posContiguous,
165	            innerDimParam, indicesNumParam, formerNumParam, formerLengthParam,
166	            tailNumParam, tailLengthParam, tileLengthParam, alphaValueParam,
167	            alphaIsSetParam, usedCoreNumParam);
168	    } else {  // kShort / int16
169	        EXEC_KERNEL_CMD(inplace_index_add_with_sorted_int16, blockDim,
170	            output, valueContiguous, sortedIndicesContiguous, posContiguous,
