130	    int64_t idx, int64_t colOffset, int64_t length, LocalTensor<T> &deltaLocal)
131	{
132	    DataCopyExtParams cp;
133	    cp.blockCount = 1;
134	    cp.blockLen = static_cast<uint32_t>(length * sizeof(T));
135	    cp.srcStride = 0;
136	    cp.dstStride = 0;
137	
138	    SetAtomicAdd<T>();
139	    DataCopyPad(outputGm[idx * innerDim_ + colOffset], deltaLocal, cp);
140	    SetAtomicNone();
141	    PipeBarrier<PIPE_ALL>();
142	}
