144	template<typename T, bool IS_FLOAT>
145	__aicore__ inline void InplaceIndexAddWithSortedKernel<T, IS_FLOAT>::Process()
146	{
147	    int64_t blockIdx = GetBlockIdx();
148	    if (blockIdx >= usedCoreNum_) return;
149	
150	    int64_t total = idxEnd_ - idxStart_;
151	    if (total <= 0) return;
152	
153	    DataCopyPadExtParams<int32_t> idxPP;
154	    idxPP.isPad = false;
155	
156	    for (int64_t bs = 0; bs < total; bs += INDEX_BATCH_SIZE) {
157	        int64_t bsz = (bs + INDEX_BATCH_SIZE <= total) ? INDEX_BATCH_SIZE : (total - bs);
158	
159	        DataCopyExtParams cp;
160	        cp.blockCount = 1;
161	        cp.blockLen = static_cast<uint32_t>(bsz * sizeof(int32_t));
162	        cp.srcStride = 0;
163	        cp.dstStride = 0;
164	
165	        LocalTensor<int32_t> idxLocal = idxBuf.Get<int32_t>();
166	        DataCopyPad(idxLocal, sortedIndicesGm[idxStart_ + bs], cp, idxPP);
167	        LocalTensor<int32_t> posLocal = posBuf.Get<int32_t>();
168	        DataCopyPad(posLocal, posGm[idxStart_ + bs], cp, idxPP);
169	        PipeBarrier<PIPE_ALL>();
170	
171	        for (int64_t b = 0; b < bsz; b++) {
172	            int64_t myIdx = static_cast<int64_t>(idxLocal.GetValue(b));
173	            int64_t myPos = static_cast<int64_t>(posLocal.GetValue(b));
174	
175	            int64_t tileNum = (innerDim_ + tileLength_ - 1) / tileLength_;
176	            for (int64_t t = 0; t < tileNum; t++) {
177	                int64_t off = t * tileLength_;
178	                int64_t len = (t == tileNum - 1) ? (innerDim_ - off) : tileLength_;
179	
180	                DataCopyExtParams cp;
181	                cp.blockCount = 1;
182	                cp.blockLen = static_cast<uint32_t>(len * sizeof(T));
183	                cp.srcStride = 0;
184	                cp.dstStride = 0;
185	                DataCopyPadExtParams<T> pp;
186	                pp.isPad = false;
187	
188	                if constexpr (IS_FLOAT && sizeof(T) == 2 && std::is_same_v<T, bfloat16_t>) {
189	                    // === BF16 PATH: load var + value, full fp32 computation, direct write ===
190	                    // This matches the reference implementation which converts var to float32,
191	                    // accumulates in float32, and only rounds to bf16 at the end.
192	
193	                    // Load var (output) row
194	                    LocalTensor<T> varLocal = varBuf.Get<T>();
195	                    DataCopyPad(varLocal, outputGm[myIdx * innerDim_ + off], cp, pp);
196	
197	                    // Load value row
198	                    LocalTensor<T> valLocal = valBuf.Get<T>();
199	                    DataCopyPad(valLocal, valueGm[myPos * innerDim_ + off], cp, pp);
200	                    PipeBarrier<PIPE_ALL>();
201	
202	                    // Compute in fp32: var_fp32 + alpha * val_fp32
203	                    LocalTensor<float> fpVar = tmpBuf2.Get<float>();
204	                    LocalTensor<float> fpVal = tmpBuf.Get<float>();
205	                    Cast(fpVar, varLocal, RoundMode::CAST_NONE, len);
206	                    Cast(fpVal, valLocal, RoundMode::CAST_NONE, len);
207	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
208	                        Muls(fpVal, fpVal, alphaValue_, len);
209	                    }
210	                    Add(fpVar, fpVar, fpVal, len);
211	
212	                    // Cast back to bf16 and write directly (no AtomicAdd; single-core safe)
213	                    LocalTensor<T> outLocal = outBuf.Get<T>();
214	                    Cast(outLocal, fpVar, RoundMode::CAST_ROUND, len);
215	                    DataCopyPad(outputGm[myIdx * innerDim_ + off], outLocal, cp);
216	                    PipeBarrier<PIPE_ALL>();
217	
218	                } else if constexpr (IS_FLOAT && sizeof(T) == 2) {
219	                    // === FP16 PATH: existing delta + AtomicAdd ===
220	                    LocalTensor<T> valLocal = valBuf.Get<T>();
221	                    LoadValue(myPos, off, len, valLocal);
222	
223	                    LocalTensor<T> outLocal = outBuf.Get<T>();
224	
225	                    LocalTensor<float> fp32 = tmpBuf.Get<float>();
226	                    Cast(fp32, valLocal, RoundMode::CAST_NONE, len);
227	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
228	                        Muls(fp32, fp32, alphaValue_, len);
229	                    }
230	                    Cast(outLocal, fp32, RoundMode::CAST_ROUND, len);
231	
232	                    WriteDelta(myIdx, off, len, outLocal);
233	
234	                } else if constexpr (IS_FLOAT && sizeof(T) == 4) {
235	                    // === FP32 PATH: existing delta + AtomicAdd ===
236	                    LocalTensor<T> valLocal = valBuf.Get<T>();
237	                    LoadValue(myPos, off, len, valLocal);
238	
239	                    LocalTensor<T> outLocal = outBuf.Get<T>();
240	
241	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
242	                        Muls(outLocal, valLocal, alphaValue_, len);
243	                    } else {
244	                        Muls(outLocal, valLocal, 1.0f, len);
245	                    }
246	
247	                    WriteDelta(myIdx, off, len, outLocal);
248	
249	                } else if constexpr (!IS_FLOAT && sizeof(T) == 4) {
250	                    // === INT32 PATH ===
251	                    LocalTensor<T> valLocal = valBuf.Get<T>();
252	                    LoadValue(myPos, off, len, valLocal);
253	
254	                    LocalTensor<T> outLocal = outBuf.Get<T>();
255	
256	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
257	                        LocalTensor<float> fp32 = tmpBuf.Get<float>();
258	                        Cast(fp32, valLocal, RoundMode::CAST_NONE, len);
259	                        Muls(fp32, fp32, alphaValue_, len);
260	                        Cast(outLocal, fp32, RoundMode::CAST_ROUND, len);
261	                    } else {
262	                        Muls(outLocal, valLocal, static_cast<T>(1), len);
263	                    }
264	
265	                    WriteDelta(myIdx, off, len, outLocal);
266	
267	                } else {
268	                    // === INT16 PATH ===
269	                    LocalTensor<T> valLocal = valBuf.Get<T>();
270	                    LoadValue(myPos, off, len, valLocal);
271	
272	                    LocalTensor<T> outLocal = outBuf.Get<T>();
273	
274	                    if (alphaIsSet_ && alphaValue_ != 1.0f) {
275	                        int16_t as = static_cast<int16_t>(static_cast<int32_t>(alphaValue_));
276	                        Muls(outLocal, valLocal, as, len);
277	                    } else {
278	                        Muls(outLocal, valLocal, static_cast<int16_t>(1), len);
279	                    }
280	
281	                    WriteDelta(myIdx, off, len, outLocal);
282	                }
283	            }
284	        }
285	    }
286	}
